describe('Product List Display - Inventory Page', () => {
  const BASE_URL = 'https://www.saucedemo.com';
  const USERNAME = 'standard_user';
  const PASSWORD = 'secret_sauce';

  beforeEach(() => {
    cy.visit(BASE_URL);
    cy.get('[data-test="username"]').type(USERNAME);
    cy.get('[data-test="password"]').type(PASSWORD);
    cy.get('[data-test="login-button"]').click();
    cy.url().should('include', '/inventory.html');
  });

  it('should display exactly 6 product cards with complete information', () => {
    // Verify exactly 6 product cards exist
    cy.get('.inventory_item').should('have.length', 6);

    // Verify each card has required elements with valid content
    cy.get('.inventory_item').each(($card) => {
      // Check product name exists and is not empty
      cy.wrap($card)
        .find('.inventory_item_name')
        .should('exist')
        .and('not.be.empty')
        .invoke('text')
        .should('have.length.greaterThan', 0);

      // Check price exists and starts with '$'
      cy.wrap($card)
        .find('.inventory_item_price')
        .should('exist')
        .invoke('text')
        .should('match', /^\$/);
    });
  });

  it('should handle edge case where product name or price might be missing', () => {
    // Verify all 6 cards have both name and price elements
    cy.get('.inventory_item').each(($card) => {
      cy.wrap($card)
        .find('.inventory_item_name')
        .should('have.length', 1);

      cy.wrap($card)
        .find('.inventory_item_price')
        .should('have.length', 1);
    });

    // Verify no card has empty name text
    cy.get('.inventory_item_name').each(($name) => {
      cy.wrap($name)
        .invoke('text')
        .then((text) => {
          expect(text.trim()).to.have.length.greaterThan(0);
        });
    });

    // Verify all prices are properly formatted with currency symbol
    cy.get('.inventory_item_price').each(($price) => {
      cy.wrap($price)
        .invoke('text')
        .then((text) => {
          expect(text).to.match(/^\$\d+\.\d{2}$/);
        });
    });
  });
});
